import sys

def main():
    data = sys.stdin.read().split()
    s1, s2, base = data[0], data[1], data[2]
    parent = list(range(26))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for a, b in zip(s1, s2):
        ra, rb = find(ord(a) - 97), find(ord(b) - 97)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb
    mp = [chr(97 + find(i)) for i in range(26)]
    print(''.join(mp[ord(c) - 97] for c in base))

main()

